-- Rollback of migration 003 (source_promotion), generated by focus.migrations.rollback_script from the forward
-- script's declared objects. Recovery is forward by default; this exists for an install that has just failed review.
-- The runner executes it in one transaction under sp_getapplock('FOCUS_FN_MIGRATIONS'); any guard stops it whole.
-- Nothing here deletes a row.
SET XACT_ABORT ON;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_PromoteSourceHead;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_RejectSourceRun;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_CompleteSourceRun;
DROP PROCEDURE IF EXISTS WEB_APP.FOCUS_FN_BeginSourceRun;
